pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amt, bool willRevert) public {
        amt = bound(amt, 1, 1 ether);

        ReceiverHelper r = new ReceiverHelper(willRevert);

        vm.deal(address(this), 2 ether);

        c.deposit{value: amt}();

        vm.deal(address(r), 1 ether);

        vm.startPrank(address(r));
        r.callDeposit{value: amt}(address(c));

        uint256 before = address(c).balance;

        bool ok;
        try c.withdraw(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.stopPrank();

        assertTrue(!willRevert || !ok);
    }
}

contract ReceiverHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    function callDeposit(address cAddr) external payable {
        (bool s, ) = cAddr.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(s, "deposit failed");
    }
}
